static void kunit_resource_test_destroy_resource ( struct kunit * test ) { struct kunit_test_resource_context * ctx = test -> priv ; struct kunit_resource * res = kunit_alloc_and_get_resource ( & ctx -> test , fake_resource_init , fake_resource_free , GFP_KERNEL , ctx ) ; kunit_put_resource ( res ) ; KUNIT_EXPECT_FALSE ( test , ctx -> is_resource_initialized ) ; KUNIT_EXPECT_TRUE ( test , list_empty ( & ctx -> test . resources ) ) ; } 